import pytest
from isort.comments import add_to_line

def test_add_to_line_no_comments():
    assert add_to_line(None, "Original string") == "Original string"


def test_add_to_line_with_unique_comments():
    assert add_to_line(["Comment 1", "Comment 2"], "Original string") == "Original string Comment 1; Comment 2"


def test_add_to_line_with_duplicate_comments():
    assert add_to_line(["Comment 1", "Comment 1", "Comment 2"], "Original string") == "Original string Comment 1; Comment 2"


def test_add_to_line_removed():
    assert add_to_line(None, "Original string", removed=True) == "Original string"

